export const SKILL_SEQUENCES = sequences;

import { Agent, GameEngine } from "../game";
import { Hex, Skill } from "../../types";
import { HexUtils } from "../utils";
import { BLOCK_HEIGHT } from "../../constants";

export class TargetingSystem {
    /**
     * 計算有效射程（考慮高地加成）
     * High Ground Bonus: 每高一層 Block，射程微量增加
     */
    public getEffectiveRange(a: Hex, targetQ: number, targetR: number, baseRange: number, engine: GameEngine): number {
        const h1 = engine.map.getTerrainHeight(a.q, a.r);
        const h2 = engine.map.getTerrainHeight(targetQ, targetR);
        const deltaH = h1 - h2;
        // 高打低：每 48px 高度 (約2層) +1 射程
        const heightBonus = deltaH > 0 ? Math.floor(deltaH / (BLOCK_HEIGHT * 2)) : 0;
        return baseRange + heightBonus;
    }

    /**
     * RTS 等級目標選取評分
     */
    public updateTarget(a: Agent, engine: GameEngine) {
        if (a.target && (a.target.hp <= 0 || a.target.banished)) a.target = null;

        let maxScore = -Infinity;
        let bestTarget: Agent | null = null;

        // 嘲諷強制鎖定
        if (a.tauntTimer > 0 && a.tauntTargetId) {
            const taunter = engine.agents.find(ag => ag.id === a.tauntTargetId);
            if (taunter && taunter.hp > 0 && !taunter.banished) {
                a.target = taunter;
                return;
            }
        }

        const isSilenced = a.silenceTimer > 0;

        for (const o of engine.agents) {
            if (o.team !== a.team && o.hp > 0 && !o.banished) {
                const dist = Math.max(0.5, HexUtils.dist(a, o));

                // 1. 距離權重: 極大幅度優先攻擊近身單位
                const distScore = 2000 / (dist + 0.5); 

                // 2. 血量權重: 殘血優先 (斬殺邏輯)
                const hpScore = (1 - o.hp / o.maxHp) * 50;

                // 3. 威脅權重: 優先鎖定正在詠唱大招的敵人
                let threatScore = 0;
                if (!isSilenced && o.castingSkillIdx !== -1) {
                    const castingSkill = o.skills[o.castingSkillIdx];
                    if (castingSkill?.tag === 'ULT') threatScore = 200; 
                    else if (castingSkill?.tag === 'ACTIVE') threatScore = 50; 
                }

                // 4. 黏著加分: 防止頻繁切換目標 (防抖)
                const stickyBonus = (a.target === o) ? 300 : 0;

                const score = distScore + hpScore + threatScore + stickyBonus;

                if (score > maxScore) {
                    maxScore = score;
                    bestTarget = o;
                }
            }
        }
        a.target = bestTarget;
    }

    /**
     * 核心：計算最佳施法目標 (Smart Cast)
     */
    public calculateOptimalTarget(source: Agent, skill: Skill, engine: GameEngine): { targetAgent: Agent | null, targetHex: Hex | null } {
        // 1. 自身爆發 (PBAOE) - Range 0 強制鎖定腳下
        if (skill.range === 0) {
            return { targetAgent: null, targetHex: { q: source.q, r: source.r } };
        }

        // 2. 遠程 AOE - 執行密度掃描
        if (skill.type === 'AOE') {
            return this.findBestAOELocation(source, skill, engine);
        }

        // 3. 單體技能 - 黏著邏輯
        if (source.target && source.target.hp > 0 && !source.target.banished) {
            const effRange = this.getEffectiveRange(source, source.target.q, source.target.r, skill.range, engine);
            if (HexUtils.dist(source, source.target) <= effRange) {
                return { targetAgent: source.target, targetHex: null };
            }
        }

        // 若當前無目標，重新搜尋
        this.updateTarget(source, engine);
        return { targetAgent: source.target, targetHex: null };
    }

    public getImpactArea(source: Agent, targetHex: Hex, skill: Skill, engine: GameEngine): Hex[] {
        if (skill.type === 'AOE') {
            const radius = skill.aoeRadius || 1;
            return HexUtils.range(targetHex, radius).filter(h => engine.map.isValid(h.q, h.r));
        }
        return [targetHex];
    }

    /**
     * 密度掃描算法 (Density Scan Algorithm) v2.0
     * 尋找能覆蓋最多高價值目標的座標
     */
    private findBestAOELocation(source: Agent, skill: Skill, engine: GameEngine) {
        const range = skill.range;
        const radius = skill.aoeRadius || 1;

        // 取得所有有效敵軍
        const enemies = engine.agents.filter(e => e.team !== source.team && e.hp > 0 && !e.banished);
        if (enemies.length === 0) return { targetAgent: null, targetHex: null };

        let bestHex: Hex | null = null;
        let maxImpact = -1;

        // 生成候選點：所有敵人的位置 + 敵人的相鄰格 (以覆蓋"兩人間隙")
        const candidates = new Set<string>();
        enemies.forEach(e => {
            candidates.add(HexUtils.key(e));
            // 如果 AOE 半徑夠大，嘗試攻擊相鄰格以覆蓋更多人
            if (radius >= 1) {
                HexUtils.neighbors(e).forEach(n => candidates.add(HexUtils.key(n)));
            }
        });

        candidates.forEach(key => {
            const [q, r] = key.split(',').map(Number);
            const targetHex = { q, r };

            // 1. 地形合法性檢查
            if (!engine.map.isValid(q, r)) return;

            // 2. 射程檢查 (嚴格遵守 Skill.range)
            const effRange = this.getEffectiveRange(source, q, r, range, engine);
            if (HexUtils.dist(source, targetHex) > effRange) return;

            // 3. 模擬衝擊評分
            let impactScore = 0;
            let hitCount = 0;

            enemies.forEach(e => {
                if (HexUtils.dist(targetHex, e) <= radius) {
                    hitCount++;
                    // 基礎分 10
                    let score = 10;

                    // 斬殺權重: 殘血加分 (Max +10)
                    score += (1 - e.hp / e.maxHp) * 10;

                    // 打斷權重: 正在詠唱大招 (+50)，普攻/小招 (+10)
                    if (e.castingSkillIdx !== -1) {
                        const s = e.skills[e.castingSkillIdx];
                        if (s?.tag === 'ULT') score += 50;
                        else score += 10;
                    }

                    impactScore += score;
                }
            });

            // 只有當能打到人時才考慮
            if (hitCount > 0 && impactScore > maxImpact) {
                maxImpact = impactScore;
                bestHex = targetHex;
            }
        });

        // 若找不到完美AOE點，退化為攻擊當前單體目標的位置
        if (!bestHex && source.target) {
            const t = source.target;
            const effRange = this.getEffectiveRange(source, t.q, t.r, range, engine);
            if (HexUtils.dist(source, t) <= effRange) {
                bestHex = { q: t.q, r: t.r };
            }
        }

        return { targetAgent: null, targetHex: bestHex };
    }
}

import { Agent, GameEngine } from "../../game";
import { Skill, AnimState } from "../../../types";
import { HexUtils } from "../../utils";
import { DamageCalculator } from "./DamageCalculator";
import { CCManager } from "./CCManager";
import { HazardManager } from "./HazardManager";
import { PhysicsEngine } from "../../physics/PhysicsEngine";
import { COMBAT_PARAM } from "../../../constants";

export class SkillExecutor {

    public executeInstantSkill(source: Agent, skill: Skill, engine: GameEngine) {
        let targets: Agent[] = [];

        // 1. 確定施法中心點 (Origin)
        // 如果是 Range 0 技能 (PBAOE)，強制中心點為自身，無視 AI 可能傳來的偏差
        let targetHex;
        if (skill.range === 0) {
            targetHex = { q: source.q, r: source.r };
        } else {
            targetHex = source.targetHex || (source.target ? {q: source.target.q, r: source.target.r} : {q: source.q, r: source.r});
        }

        // 2. 獲取受影響區域 (Impact Area)
        const impactCells = engine.movement.targeting.getImpactArea(source, targetHex, skill, engine);

        // 3. 視覺中心點 (Visual Origin)
        const p = HexUtils.toPx(targetHex.q, targetHex.r, engine.mapConfig);
        const origin = { x: p.x, y: p.y };

        // 4. 判定受擊目標
        if (skill.type === 'AOE' || impactCells.length > 1) {
            impactCells.forEach(cell => {
                const u = engine.getAgentAt(cell.q, cell.r);
                if (u && u.hp > 0 && !u.banished) {
                    // 敵我識別 (友軍傷害檢查)
                    // 目前邏輯：傷害技打敵人，治療技打友軍
                    if (skill.power >= 0 && u.team !== source.team) targets.push(u);
                    else if (skill.power < 0 && u.team === source.team) targets.push(u);
                }
            });

            // 觸發 AOE 視覺事件
            engine.events.push({ type: 'IMPACT_AOE', pos: origin, skill, color: skill.color });

            // 生成地面災害 (Hazards)
            HazardManager.spawnHazards(source, impactCells, skill, engine);
        } else {
            // 單體技能邏輯
            if (source.target && source.target.hp > 0 && !source.target.banished) {
                const effRange = engine.movement.getEffectiveRange(source, source.target.q, source.target.r, skill.range, engine);
                if (HexUtils.dist(source, source.target) <= effRange) {
                    targets.push(source.target);
                }
            }
        }

        // 特殊情況：自身單體 Buff (例如治療自己)
        if (targets.length === 0 && skill.power <= 0 && skill.type === 'SINGLE') {
            targets.push(source);
        }

        // 5. 結算所有目標
        targets.forEach(t => {
            const dist = HexUtils.dist(source, t);
            // 視覺連線：如果距離遠，畫光束；距離近，畫斬擊
            if (dist > 1) {
                engine.events.push({ type: 'VISUAL_BEAM', pos: { x: t.px, y: t.py }, sourceId: source.id, targetId: t.id, skill, color: skill.color });
            } else {
                engine.events.push({ type: 'VISUAL_SLASH', pos: { x: t.px, y: t.py }, sourceId: source.id, targetId: t.id, skill, color: skill.color });
            }
            this.resolveHit(source, t, skill, origin, engine);
        });

        if (skill.tag !== 'BASIC') {
            engine.events.push({ type: 'CAST_FINISH', pos: {x: source.px, y: source.py}, skill: skill });
        }
    }

    public resolveHit(source: Agent, target: Agent, skill: Skill, origin: {x: number, y: number} | undefined, engine: GameEngine) {
        const result = DamageCalculator.calculate(source, target, skill);

        // 閃避處理
        if (result.isMiss) {
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "MISS", color: "#94a3b8" });
            engine.log(source, 'HIT', '未命中', target.id, `${skill.name} 被閃避`);
            return;
        }

        const oldHp = Math.ceil(target.hp);
        if (result.shieldAbsorb > 0) target.shield -= result.shieldAbsorb;

        // 應用傷害/治療
        target.hp = Math.min(target.maxHp, target.hp + result.finalValue);

        // 吸血處理
        if (result.vampAmount > 0 && source.hp > 0) {
            source.hp = Math.min(source.maxHp, source.hp + result.vampAmount);
            engine.events.push({ type: 'HEAL', pos: {x: source.px, y: source.py}, value: result.vampAmount, color: '#86efac' });
            engine.log(source, 'HEAL', '吸血', '自身', `獲得治療 ${result.vampAmount}`);
        }

        const isDamage = result.finalValue < 0;
        const absVal = Math.abs(result.finalValue);

        if (isDamage) { 
            target.setAnim(AnimState.HIT);
            target.hitFlashTimer = COMBAT_PARAM.HIT_FLASH_DURATION;

            // 物理擊退力道計算
            const originPx = origin ? origin : {x: source.px, y: source.py};
            // 傷害越高，擊退感越強 (Min 100, Max 600)
            const damageForce = Math.min(600, 100 + absVal * 1.5);
            PhysicsEngine.applyImpulse(target, originPx, damageForce, 0.4);

            engine.log(source, 'HIT', '命中', target.id, `${skill.name} 造成 ${absVal} 傷害${result.isCrit ? ' (暴擊!)' : ''}`);
        } else {
            engine.log(source, 'HEAL', '治療', target.id, `${skill.name} 恢復 ${absVal} 生命`);
        }

        // 發送事件供前端顯示
        engine.events.push({
            type: isDamage ? 'DAMAGE' : 'HEAL',
            pos: { x: target.px, y: target.py },
            value: result.finalValue,
            sourceId: source.id,
            targetId: target.id,
            skill: skill,
            color: skill.color
        });

        // 應用控制效果 (CC)
        CCManager.applyCC(source, target, skill, skill.ccType, skill.ccDur, skill.ccForce, origin, engine);
        CCManager.applyCC(source, target, skill, skill.ccType2, skill.ccDur2, skill.ccForce2, origin, engine);

        // 死亡判定
        if (oldHp > 0 && target.hp <= 0) {
            engine.events.push({ type: 'KILL', pos: { x: target.px, y: target.py }, sourceId: source.id, targetId: target.id });
        }
    }
}

